import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.fail;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

import com.netflix.frigga.NameConstants;
import org.mockito.Mockito;

public class AppVersionTest {

    @Test
    public void parseName_DoesNotThrowException_WhenGivenAValidAmiName() {
        String amiName = "1.2.3-4";
        AppVersion appVersion = AppVersion.parseName(amiName);
        assertNotNull(appVersion);
    }

    @Test
    public void parseName_ThrowsNoSuchAlgorithmException_WhenGivenANonCompliantAmiName() {
        String amiName = "abc.def.ghi-jkl";
        try {
            AppVersion.parseName(amiName);
            fail("Expected exception not thrown");
        } catch (Exception e) {
            assertTrue(e instanceof java.lang.NoSuchAlgorithmException);
        }
    }

    @Test
    public void compare_to_DoesNotThrowException_WhenGivenTwoValidAppVersions() {
        AppVersion appVersion1 = new AppVersion("1.2.3-4", "com.example.app");
        AppVersion appVersion2 = new AppVersion("5.6.7-8", "com.example.app2");
        int result = appVersion1.compareTo(appVersion2);
        assertEquals(-1, result);
    }

    @Test
    public void compare_to_DoesNotThrowException_WhenGivenTwoInvalidAppVersions() {
        AppVersion appVersion1 = new AppVersion("abc.def.ghi-jkl", "com.example.app");
        AppVersion appVersion2 = new AppVersion("def.ghi.jkl-mno", "com.example.app2");
        int result = appVersion1.compareTo(appVersion2);
        assertEquals(-1, result);
    }

    @Test
    public void getAppVersionPattern_ReturnsPattern_WhenGivenANormalAppVersion() {
        Matcher matcher = Pattern.compile("[0-9]+\\.[0-9]+\\.[0-9]-[a-z]+").matcher("1.2.3-4");
        assertTrue(matcher.matches());
    }

    @Test
    public void getAppVersionPattern_DoesNotReturnMatch_WhenGivenAnInvalidAmmiName() {
        Pattern pattern = AppVersion.getAppVersionPattern();
        Matcher matcher = pattern.matcher("abc.def.ghi-jkl");
        assertFalse(matcher.matches());
    }

    @Test
    public void getPackageName_ReturnsPackageName() {
        AppVersion appVersion = new AppVersion("1.2.3-4", "com.example.app");
        assertEquals("com.example.app", appVersion.getPackageName());
    }

    @Test
    public void getVersion_ReturnsVersion() {
        AppVersion appVersion = new AppVersion("1.2.3-4", "com.example.app");
        assertEquals("1.2.3-4", appVersion.getVersion());
    }

    @Test
    public void getBuildJobName_ReturnsBuildJobName() {
        AppVersion appVersion = new AppVersion("1.2.3-4", "com.example.app");
        assertEquals("build-1234", appVersion.getBuildJobName());
    }

    @Test
    public void getBuildNumber_ReturnsBuildNumber() {
        AppVersion appVersion = new AppVersion("1.2.3-4", "com.example.app");
        assertEquals("1234", appVersion.getBuildNumber());
    }

    @Test
    public void getCommit_ReturnsCommit() {
        AppVersion appVersion = new AppVersion("1.2.3-4", "com.example.app");
        assertEquals("commit-id", appVersion.getCommit());
    }

    @Test
    public void getChangelist_DoesNotReturnString_WhenGivenANormalAppVersion() {
        String changelist = AppVersion.parseName("1.2.3-4").getChangelist();
        assertNull(changelist);
    }

    @Test
    public void getChangelist_ReturnsCorrectValueForNormalAmmiName() {
        AppVersion appVersion = AppVersion.parseName(NameConstants.NORMALLY_formatted);
        String changelist = appVersion.getChangelist();
        assertEquals("123", changelist);
    }

    @Test
    public void toString_ReturnsCorrectString_WhenGivenANormalAppVersion() {
        AppVersion appVersion = new AppVersion("1.2.3-4", "com.example.app");
        String expected = "build-1234@com.example.app, 1.2.3-4";
        assertEquals(expected, appVersion.toString());
    }

    @Test
    public void hashCode_DoesNotThrowException_WhenGivenANormalAppVersion() {
        AppVersion appVersion = new AppVersion("1.2.3-4", "com.example.app");
        int expectedHash = 1234 + 42;
        assertEquals(expectedHash, appVersion.hashCode());
    }

    @Test
    public void equals_ThrowsException_WhenGivenANormalAppVersionAndDifferentValue() {
        AppVersion appVersion1 = new AppVersion("1.2.3-4", "com.example.app");
        AppVersion appVersion2 = new AppVersion("5.6.7-8", "com.example.app");
        boolean result = appVersion1.equals(appVersion2);
        assertFalse(result);
    }

    @Test
    public void equals_ReturnsCorrectValueForNormalAppVersions() {
        AppVersion appVersion1 = new AppVersion("1.2.3-4", "com.example.app");
        AppVersion appVersion2 = new AppVersion("1.2.3-4", "com.example.app");
        boolean result = appVersion1.equals(appVersion2);
        assertTrue(result);
    }
}
